const fs = require('fs');
const zlib = require('zlib');
const path = require('path');

// Read the docx as a zip manually using Node's built-in modules
// .docx is a ZIP file; let's parse it manually
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find local file headers and extract word/document.xml
// ZIP local file header signature: 0x04034b50
let offset = 0;
const files = [];
while (offset < buf.length - 4) {
    const sig = buf.readUInt32LE(offset);
    if (sig !== 0x04034b50) break;

    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const fnLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const fileName = buf.toString('utf8', offset + 30, offset + 30 + fnLen);
    const dataStart = offset + 30 + fnLen + extraLen;

    if (fileName === 'word/document.xml') {
        let data;
        if (compMethod === 8) {
            data = zlib.inflateRawSync(buf.slice(dataStart, dataStart + compSize));
        } else {
            data = buf.slice(dataStart, dataStart + uncompSize);
        }

        // Parse XML to extract text
        const xml = data.toString('utf8');
        const texts = [];
        let currentPara = [];
        const tagRegex = /<[^>]+>|[^<]+/g;
        let match;
        let inT = false;
        while ((match = tagRegex.exec(xml)) !== null) {
            const token = match[0];
            if (token.startsWith('<w:t')) { inT = true; continue; }
            if (token === '</w:t>') { inT = false; continue; }
            if (token.startsWith('<w:p ') || token === '<w:p>') {
                if (currentPara.length > 0) { texts.push(currentPara.join('')); currentPara = []; }
                continue;
            }
            if (token === '</w:p>') {
                if (currentPara.length > 0) { texts.push(currentPara.join('')); currentPara = []; }
                continue;
            }
            if (inT && !token.startsWith('<')) {
                currentPara.push(token);
            }
        }
        if (currentPara.length > 0) texts.push(currentPara.join(''));
        console.log(texts.join('\n'));
        break;
    }

    offset = dataStart + compSize;
}
"
